// C++: Subscript returning Lvalue reference
// Enables modification and reference binding
class CustomArray {
    int arr[5] = {0};
public:
    // Subscript operator returns a reference (Lvalue)
    int& operator[](size_t index) {
        return arr[index];
    }
};

CustomArray ca;
ca[2] = 100;      // Lvalue: Assignment
(ca[2])++;        // Lvalue: Modification
int* p = &(ca[1]);// Lvalue: Addressable
int& ref = ca[0]; // Lvalue: Reference binding
int rval = ca[4]; // Used as rvalue
